  ('economics/finance-and-capital-markets/alternative-investments/infrastructure', 'economics', 'economics/finance-and-capital-markets/alternative-investments', 'Infrastructure', 'infrastructure', '', 5, 2),
  ('economics/finance-and-capital-markets/corporate-issuers/core-concepts', 'economics', 'economics/finance-and-capital-markets/corporate-issuers', 'Core Concepts', 'core-concepts', 'What a corporate issuer is, the main forms of business organization, and how companies raise and allocate capital; and the key players — shareholders, the board, management, creditors, and other stakeholders.', 0, 2),
  ('economics/finance-and-capital-markets/corporate-issuers/stakeholder-management', 'economics', 'economics/finance-and-capital-markets/corporate-issuers', 'Stakeholder Management', 'stakeholder-management', 'Identifying a company''s stakeholders (shareholders, creditors, employees, customers, suppliers, regulators, and the community) and managing their sometimes-competing interests.', 1, 2),
  ('economics/finance-and-capital-markets/corporate-issuers/corporate-governance', 'economics', 'economics/finance-and-capital-markets/corporate-issuers', 'Corporate Governance', 'corporate-governance', 'Corporate governance — the system of controls and incentives that directs a company; the conflicts of interest among managers, shareholders, and other stakeholders, the mechanisms that manage them, and their risks and benefits.', 2, 2),
  ('economics/finance-and-capital-markets/corporate-issuers/esg-considerations-in-investing', 'economics', 'economics/finance-and-capital-markets/corporate-issuers', 'ESG Considerations in Investing', 'esg-considerations-in-investing', 'How environmental and social considerations are integrated into investing (ESG), and why they matter to both issuers and investors.', 3, 2),
  ('economics/finance-and-capital-markets/corporate-issuers/capital-structure-and-leverage', 'economics', 'economics/finance-and-capital-markets/corporate-issuers', 'Capital Structure and Leverage', 'capital-structure-and-leverage', 'How companies make use of leverage — financing with debt alongside equity — and the benefits and risks of doing so.', 4, 2),
  ('economics/finance-and-capital-markets/corporate-issuers/working-capital-and-liquidity', 'economics', 'economics/finance-and-capital-markets/corporate-issuers', 'Working Capital and Liquidity', 'working-capital-and-liquidity', 'How companies manage working capital and liquidity to meet short-term operational needs.', 5, 2),
  ('economics/finance-and-capital-markets/derivatives/core-concepts', 'economics', 'economics/finance-and-capital-markets/derivatives', 'Core Concepts', 'core-concepts', 'What a derivative is and how derivative markets work; the two families — forward commitments (forwards, futures, swaps) and contingent claims (options) — and the benefits and risks of using them.', 0, 2),
  ('economics/finance-and-capital-markets/derivatives/forwards-and-futures', 'economics', 'economics/finance-and-capital-markets/derivatives', 'Forwards and Futures', 'forwards-and-futures', 'Forward and futures contracts lock in a price today for a transaction later; how futures differ from forwards (exchange-traded, standardized, marked to market daily).', 1, 2),
  ('economics/finance-and-capital-markets/derivatives/swaps', 'economics', 'economics/finance-and-capital-markets/derivatives', 'Swaps', 'swaps', 'Swaps as a series of forward commitments to exchange cash flows over time, such as interest rate swaps.', 2, 2),
  ('economics/finance-and-capital-markets/derivatives/contingent-claims-options', 'economics', 'economics/finance-and-capital-markets/derivatives', 'Contingent Claims (Options)', 'contingent-claims-options', 'Options as contingent claims — the right, but not the obligation, to buy (call) or sell (put) an underlying; their payoffs and basic uses.', 3, 2),
  ('economics/finance-and-capital-markets/derivatives/arbitrage-and-replication', 'economics', 'economics/finance-and-capital-markets/derivatives', 'Arbitrage and Replication', 'arbitrage-and-replication', 'Arbitrage — a riskless profit from mispricing — and how replicating a derivative''s payoff with the underlying plus cash enforces its price under the no-arbitrage condition.', 4, 2),
  ('economics/finance-and-capital-markets/derivatives/pricing-derivatives-from-the-underlying', 'economics', 'economics/finance-and-capital-markets/derivatives', 'Pricing Derivatives from the Underlying', 'pricing-derivatives-from-the-underlying', 'Why a derivative''s price is tied to the price of its underlying asset, using arbitrage, replication, and the cost of carry.', 5, 2),
