  ('economics/quantitative-foundations/portfolio-mathematics/probability-models-for-portfolio-return-and-risk', 'economics', 'economics/quantitative-foundations/portfolio-mathematics', 'Probability Models for Portfolio Return and Risk', 'probability-models-for-portfolio-return-and-risk', 'Calculate and interpret the expected value, variance, standard deviation, covariances, and correlations of portfolio returns.', 1, 2),
